contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string memory description) public {
        vm.assume(caller != address(0));
        // Set jojoTeam to some address
        address jojoTeam = makeAddr("jojoTeam");
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(uint160(jojoTeam)))); // slot 1 is jojoTeam

        // Also ensure caller is jojoTeam to satisfy onlyJojoTeam
        vm.assume(caller == jojoTeam);

        // Call newEmergencyOracle as caller (which is jojoTeam)
        vm.prank(caller);
        c.newEmergencyOracle(description);

        // The oracle address is emitted in the event; we need to compute it
        // Use the deterministic address: address(uint160(uint256(keccak256(abi.encodePacked(
        //     bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x01)
        // )))))? That's approximate. Instead, we can compute using CREATE address.
        // Since EmergencyOracle is created via 'new' without salt, address = computeCreateAddress(address(c), nonce).
        uint256 nonce = vm.getNonce(address(c));
        address expectedOracle = computeCreateAddress(address(c), nonce);

        // Get the owner of that oracle
        EmergencyOracle oracle = EmergencyOracle(expectedOracle);
        address owner = oracle.owner();

        // The owner should be the caller (msg.sender) not jojoTeam
        assertTrue(owner == caller, "Owner should be the caller, not jojoTeam");
    }

    // Helper to compute create address
    function computeCreateAddress(address deployer, uint256 nonce) internal pure returns (address) {
        // Based on EIP-161
        bytes memory data;
        if (nonce == 0) return address(0);
        while (nonce > 0) {
            data = abi.encodePacked(data, bytes1(uint8(nonce % 256)));
            nonce /= 256;
        }
        return address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xd6), bytes1(0x94), deployer, bytes1(uint8(nonce % 256))
        )))));
    }
}

